input.sparql:
SELECT ?zone ?sensor ?stream WHERE {
  ?zone brickhasPoint ?sensor ;
         rdfs:label ?zone_label.
  ?sensor brick:measures brick:Electric_Power ;
          ref:hasTimeseriesId ?stream.
  VALUES ?zone_label {
    "Core_bottom"
    "Perimeter_bot_ZN_4"
    "Perimeter_top_ZN_1"
  }
}
